+namespace Microsoft.Integration.Shopify.Test;
+
+using Microsoft.Integration.Shopify;
+using System.TestLibraries.Utilities;
+using Microsoft.Inventory.Item;
+using Microsoft.Finance.Currency;
+
+/// <summary>
+/// Codeunit Shpfy Create Item Currency Test (ID 139635).
+/// </summary>
+codeunit 139635 "Shpfy CreateItem Currency Test"
+{
+    Subtype = Test;
+    TestType = Uncategorized;
+    TestPermissions = Disabled;
+
+    var
+        LibraryAssert: Codeunit "Library Assert";
+
+    [Test]
+    procedure UnitTestCreateItemWithShopCurrencyConvertsPrices()
+    var
+        Item: Record Item;
+        Shop: Record "Shpfy Shop";
+        ShopifyProduct: Record "Shpfy Product";
+        ShopifyVariant: Record "Shpfy Variant";
+        Currency: Record Currency;
+        CurrencyExchangeRate: Record "Currency Exchange Rate";
+        ProductInitTest: Codeunit "Shpfy Product Init Test";
+        InitializeTest: Codeunit "Shpfy Initialize Test";
+        CurrencyCode: Code[10];
+        ExchangeRateAmt: Decimal;
+        ExpectedUnitCost: Decimal;
+        ExpectedUnitPrice: Decimal;
+    begin
+        // [SCENARIO] When creating an Item from a Shopify Product and the Shop has a non-empty Currency Code,
+        // the Unit Cost and Unit Price should be converted from foreign currency to LCY using the exchange rate.
+
+        // [GIVEN] The Shop with the setting "SKU Mapping" = "Item No." and a foreign currency code with exchange rate.
+        Shop := InitializeTest.CreateShop();
+        Shop."SKU Mapping" := "Shpfy SKU Mapping"::"Item No.";
+
+        CurrencyCode := 'DKK';
+        if not Currency.Get(CurrencyCode) then begin
+            Currency.Init();
+            Currency.Code := CurrencyCode;
+            Currency."Amount Rounding Precision" := 0.01;
+            Currency.Insert();
+        end;
+
+        ExchangeRateAmt := 100;
+        CurrencyExchangeRate.SetRange("Currency Code", CurrencyCode);
+        if not CurrencyExchangeRate.FindFirst() then begin
+            CurrencyExchangeRate.Init();
+            CurrencyExchangeRate."Currency Code" := CurrencyCode;
+            CurrencyExchangeRate."Starting Date" := 0D;
+            CurrencyExchangeRate."Exchange Rate Amount" := ExchangeRateAmt;
+            CurrencyExchangeRate."Relational Exch. Rate Amount" := 15; // 1 LCY = ~6.67 FCY
+            CurrencyExchangeRate."Adjustment Exch. Rate Amount" := ExchangeRateAmt;
+            CurrencyExchangeRate."Relational Adjmt Exch Rate Amt" := 15;
+            CurrencyExchangeRate.Insert();
+        end;
+
+        Shop."Currency Code" := CurrencyCode;
+        Shop.Modify();
+
+        // [GIVEN] A Shopify variant with non-zero Unit Cost and Price (in foreign currency).
+        ShopifyVariant := ProductInitTest.CreateStandardProduct(Shop);
+
+        // Ensure non-zero Price (CreateStandardProduct doesn't set Price)
+        ShopifyVariant.Price := 5000;
+        ShopifyVariant."Unit Cost" := 1000;
+        ShopifyVariant.Modify();
+        ShopifyVariant.SetRecFilter();
+
+        // [WHEN] Executing "Shpfy Create Item" with the variant record.
+        Codeunit.Run(Codeunit::"Shpfy Create Item", ShopifyVariant);
+
+        // [THEN] The Item should be created.
+        LibraryAssert.IsFalse(IsNullGuid(ShopifyVariant."Item SystemId"), 'Item SystemId <> NullGuid');
+        LibraryAssert.IsTrue(Item.GetBySystemId(ShopifyVariant."Item SystemId"), 'Get Item');
+
+        // [THEN] The Unit Cost and Unit Price should be converted from FCY to LCY, not stored as the raw Shopify values.
+        // With exchange rate 100 FCY = 15 LCY, the conversion factor is 15/100 = 0.15
+        // So 1000 DKK -> Round(1000 * 15 / 100) = 150 LCY, and 5000 DKK -> Round(5000 * 15 / 100) = 750 LCY
+        ExpectedUnitCost := Round(CurrencyExchangeRate.ExchangeAmtFCYToLCY(
+            WorkDate(), CurrencyCode, 1000,
+            CurrencyExchangeRate.ExchangeRate(WorkDate(), CurrencyCode)));
+        ExpectedUnitPrice := Round(CurrencyExchangeRate.ExchangeAmtFCYToLCY(
+            WorkDate(), CurrencyCode, 5000,
+            CurrencyExchangeRate.ExchangeRate(WorkDate(), CurrencyCode)));
+
+        LibraryAssert.AreNotEqual(ShopifyVariant."Unit Cost", Item."Unit Cost",
+            'Unit Cost should not equal the raw Shopify variant value when shop has a currency code');
+        LibraryAssert.AreNotEqual(ShopifyVariant.Price, Item."Unit Price",
+            'Unit Price should not equal the raw Shopify variant value when shop has a currency code');
+        LibraryAssert.AreEqual(ExpectedUnitCost, Item."Unit Cost", 'Unit Cost should be converted from FCY to LCY');
+        LibraryAssert.AreEqual(ExpectedUnitPrice, Item."Unit Price", 'Unit Price should be converted from FCY to LCY');
+    end;
+}
